// Aggregate computes aggregate values for Image.
func (a ImageActions) Aggregate(ctx context.Context, opts ...query.ImageAggregateOption) (*query.ImageAggregateResult, error) {
	selParts := []string{"COUNT(*)"}
	for _, opt := range opts {
		fn := strings.ToUpper(opt.Fn)
		if fn != "AVG" && fn != "SUM" && fn != "MIN" && fn != "MAX" {
			return nil, fmt.Errorf("invalid aggregate function %q", opt.Fn)
		}
		field, err := quoteImageField(a.client, opt.Field)
		if err != nil {
			return nil, err
		}
		selParts = append(selParts, fmt.Sprintf("%s(%s)", fn, field))
	}
	q := fmt.Sprintf("SELECT %s FROM %s", strings.Join(selParts, ", "), quotedImageTable(a.client))
	row := a.client.executor.QueryRowContext(ctx, q)
	result := &query.ImageAggregateResult{
		Avg: make(map[string]*float64),
		Sum: make(map[string]*float64),
		Min: make(map[string]any),
		Max: make(map[string]any),
	}
	aggVals := make([]sql.NullFloat64, len(opts))
	scanDest := make([]any, 0, 1+len(opts))
	scanDest = append(scanDest, &result.Count)
	for i := range opts {
		scanDest = append(scanDest, &aggVals[i])
	}
	if err := row.Scan(scanDest...); err != nil {
		return nil, fmt.Errorf("Image.Aggregate: %w", err)
	}
	for i, opt := range opts {
		if aggVals[i].Valid {
			v := aggVals[i].Float64
			switch strings.ToLower(opt.Fn) {
			case "avg":
				result.Avg[opt.Field] = &v
			case "sum":
				result.Sum[opt.Field] = &v
			case "min":
				result.Min[opt.Field] = v
			case "max":
				result.Max[opt.Field] = v
			}
		}
	}
	return result, nil
}

// GroupBy performs a GROUP BY query on Image.
func (a ImageActions) GroupBy(ctx context.Context, fields []string, opts ...query.ImageAggregateOption) ([]query.ImageGroupByResult, error) {
	selParts := make([]string, 0, len(fields)+1+len(opts))
	groupFields := make([]string, len(fields))
	for i, field := range fields {
		quoted, err := quoteImageField(a.client, field)
		if err != nil {
			return nil, err
		}
		groupFields[i] = quoted
	}
	selParts = append(selParts, groupFields...)
	selParts = append(selParts, "COUNT(*)")
	for _, opt := range opts {
		fn := strings.ToUpper(opt.Fn)
		if fn != "AVG" && fn != "SUM" && fn != "MIN" && fn != "MAX" {
			return nil, fmt.Errorf("invalid aggregate function %q", opt.Fn)
		}
		field, err := quoteImageField(a.client, opt.Field)
		if err != nil {
			return nil, err
		}
		selParts = append(selParts, fmt.Sprintf("%s(%s)", fn, field))
	}
	q := fmt.Sprintf("SELECT %s FROM %s GROUP BY %s", strings.Join(selParts, ", "), quotedImageTable(a.client), strings.Join(groupFields, ", "))
	rows, err := a.client.executor.QueryContext(ctx, q)
	if err != nil {
		return nil, fmt.Errorf("Image.GroupBy: %w", err)
	}
	defer rows.Close()
	var results []query.ImageGroupByResult
	for rows.Next() {
		r := query.ImageGroupByResult{
			Group: make(map[string]any),
			Avg:   make(map[string]*float64),
			Sum:   make(map[string]*float64),
			Min:   make(map[string]any),
			Max:   make(map[string]any),
		}
		groupVals := make([]any, len(fields))
		scanDest := make([]any, 0, len(fields)+1+len(opts))
		for i := range fields {
			groupVals[i] = new(any)
			scanDest = append(scanDest, groupVals[i])
		}
		scanDest = append(scanDest, &r.Count)
		aggVals := make([]sql.NullFloat64, len(opts))
		for i := range opts {
			scanDest = append(scanDest, &aggVals[i])
		}
		if err := rows.Scan(scanDest...); err != nil {
			return nil, fmt.Errorf("Image.GroupBy scan: %w", err)
		}
		for i, f := range fields {
			r.Group[f] = *(groupVals[i].(*any))
		}
		for i, opt := range opts {
			if aggVals[i].Valid {
				v := aggVals[i].Float64
				switch strings.ToLower(opt.Fn) {
				case "avg":
					r.Avg[opt.Field] = &v
				case "sum":
					r.Sum[opt.Field] = &v
				case "min":
					r.Min[opt.Field] = v
				case "max":
					r.Max[opt.Field] = v
				}
			}
		}
		results = append(results, r)
	}
	return results, rows.Err()
}
